      backup_text =
        "# COMPANION PLANTING GRID - A Night Garden Simulation #\n\
         # Plants sense their neighbors under the moonlight #\n\n\
         type Crop = String in\n\
         type Row = Int in\n\
         type Col = Int in\n\
         type Health = Int in\n\n\
         type Cell = (\n\
         crop = Crop,\n\
         health = Health\n\
         ) in\n\n\
         type Field = [[Cell]] in\n\n\
         type Effect =\n\
         + Beneficial\n\
         + Harmful\n\
         + Neutral\n\
         in\n\n\
         type Model = (\n\
         field = Field,\n\
         currentSeed = Crop,\n\
         seedInventory = [Crop]\n\
         ) in\n\n\
         type Action =\n\
         + PlantCrop(Row, Col)\n\
         + HarvestCrop(Row, Col)\n\
         + CalculateHealth\n\
         + SelectSeed(Int)\n\
         + WaterAll\n\
         in\n\n\
         let clamp : Int -> Int =\n\
         fun x ->\n\
         if x < 0 then 0\n\
         else if x > 100 then 100\n\
         else x\n\
         in\n\n\
         let emptyCell : Cell = (crop = \"\", health = 0) in\n\n\
         let makeCell : Crop -> Cell =\n\
         fun crop -> (crop = crop, health = 50)\n\
         in\n\n\
         let companionEffect : (Crop, Crop) -> Effect =\n\
         fun (crop1, crop2) ->\n\
         if crop1 == \"\" || crop2 == \"\" then Neutral\n\
         else if crop1 == crop2 then Neutral\n\
         else if (crop1 == \"tomato\" && crop2 == \"basil\") ||\n\
         (crop1 == \"basil\" && crop2 == \"tomato\") then Beneficial\n\
         else if (crop1 == \"carrot\" && crop2 == \"corn\") ||\n\
         (crop1 == \"corn\" && crop2 == \"carrot\") then Beneficial\n\
         else if (crop1 == \"tomato\" && crop2 == \"carrot\") ||\n\
         (crop1 == \"carrot\" && crop2 == \"tomato\") then Harmful\n\
         else Neutral\n\
         in\n\n\
         let effectToModifier : Effect -> Int =\n\
         fun effect ->\n\
         case effect\n\
         | Beneficial => 10\n\
         | Harmful => -10\n\
         | Neutral => 0\n\
         end\n\
         in\n\n\
         let getCell : (Field, Row, Col) -> Cell =\n\
         fun (field, row, col) ->\n\
         if row < 0 || col < 0 then emptyCell\n\
         else if row >= length(field) then emptyCell\n\
         else\n\
         let rowData = nth(field, row) in\n\
         if col >= length(rowData) then emptyCell\n\
         else nth(rowData, col)\n\
         in\n\n\
         let setCell : (Field, Row, Col, Cell) -> Field =\n\
         fun (field, row, col, cell) ->\n\
         mapi(field, fun (i, r) ->\n\
         if i == row\n\
         then mapi(r, fun (j, c) ->\n\
         if j == col then cell else c)\n\
         else r)\n\
         in\n\n\
         let getNeighborCells : (Field, Row, Col) -> [Cell] =\n\
         fun (field, row, col) ->\n\
         [\n\
         getCell(field, row - 1, col),\n\
         getCell(field, row + 1, col),\n\
         getCell(field, row, col - 1),\n\
         getCell(field, row, col + 1)\n\
         ]\n\
         in\n\n\
         let neighborModifier : (Field, Row, Col) -> Int =\n\
         fun (field, row, col) ->\n\
         let cell = getCell(field, row, col) in\n\
         if cell.crop == \"\" then 0\n\
         else\n\
         let neighbors = getNeighborCells(field, row, col) in\n\
         let effects = map(neighbors, fun neighbor ->\n\
         companionEffect(cell.crop, cell.crop)\n\
         ) in\n\
         let modifiers = map(effects, effectToModifier) in\n\
         fold_left(modifiers, fun (acc, m) -> acc + m, 0)\n\
         in\n\n\
         let recalculateCellHealth : (Field, Row, Col) -> Cell =\n\
         fun (field, row, col) ->\n\
         let cell = getCell(field, row, col) in\n\
         if cell.crop == \"\" then emptyCell\n\
         else\n\
         let modifier = neighborModifier(field, row, col) in\n\
         let baseHealth = 50 in\n\
         (crop = cell.crop, health = clamp(baseHealth + modifier))\n\
         in\n\n\
         let recalculateAllHealth : Field -> Field =\n\
         fun field ->\n\
         mapi(field, fun (row, rowData) ->\n\
         mapi(rowData, fun (col, _) ->\n\
         recalculateCellHealth(field, row, col)\n\
         )\n\
         )\n\
         in\n\n\
         let emptyField : Field =\n\
         [\n\
         [emptyCell, emptyCell, emptyCell],\n\
         [emptyCell, emptyCell, emptyCell],\n\
         [emptyCell, emptyCell, emptyCell]\n\
         ]\n\
         in\n\n\
         let init : Model = (\n\
         field = emptyField,\n\
         currentSeed = \"tomato\",\n\
         seedInventory = [\"tomato\", \"basil\", \"carrot\", \"corn\", \
         \"sunflower\"]\n\
         ) in\n\n\
         let update : (Model, Action) -> Model =\n\
         fun (model, action) ->\n\
         case action\n\
         | PlantCrop(row, col) =>\n\
         let currentCell = getCell(model.field, row, col) in\n\
         if currentCell.crop != \"\" then model\n\
         else\n\
         let newCell = makeCell(model.currentSeed) in\n\
         let newField = setCell(model.field, row, col, newCell) in\n\
         (\n\
         field = newField,\n\
         currentSeed = model.currentSeed,\n\
         seedInventory = model.seedInventory\n\
         )\n\
         | HarvestCrop(row, col) =>\n\
         let newField = setCell(model.field, row, col, emptyCell) in\n\
         (\n\
         field = newField,\n\
         currentSeed = model.currentSeed,\n\
         seedInventory = model.seedInventory\n\
         )\n\
         | CalculateHealth =>\n\
         let newField = recalculateAllHealth(model.field) in\n\
         (\n\
         field = newField,\n\
         currentSeed = model.currentSeed,\n\
         seedInventory = model.seedInventory\n\
         )\n\
         | SelectSeed(idx) =>\n\
         (\n\
         field = model.field,\n\
         currentSeed = nth(model.seedInventory, idx),\n\
         seedInventory = model.seedInventory\n\
         )\n\
         | WaterAll =>\n\
         let wateredField = map(model.field, fun row ->\n\
         map(row, fun cell ->\n\
         if cell.crop == \"\" then cell\n\
         else (crop = cell.crop, health = clamp(cell.health + 5))\n\
         )\n\
         ) in\n\
         (\n\
         field = wateredField,\n\
         currentSeed = model.currentSeed,\n\
         seedInventory = model.seedInventory\n\
         )\n\
         end\n\
         in\n\n\
         let garden : (Model, [Action]) -> Model =\n\
         fun (model: Model, actions: [Action]) ->\n\
         fold_left(actions, update, model)\n\
         in\n\n\
         let healthAt : (Model, Row, Col) -> Health =\n\
         fun (model, row, col) ->\n\
         let cell = getCell(model.field, row, col) in\n\
         cell.health\n\
         in\n\n\
         let cropAt : (Model, Row, Col) -> Crop =\n\
         fun (model, row, col) ->\n\
         let cell = getCell(model.field, row, col) in\n\
         cell.crop\n\
         in\n\n\
         # ===== TESTS ===== #\n\n\
         hint \"can plant a crop\"\n\
         test\n\
         let m = update(init, PlantCrop(0, 0)) in\n\
         cropAt(m, 0, 0) == \"tomato\"\n\
         end;\n\n\
         hint \"new crop starts at base health\"\n\
         test\n\
         let m = update(init, PlantCrop(1, 1)) in\n\
         healthAt(m, 1, 1) == 50\n\
         end;\n\n\
         hint \"cannot plant on occupied cell\"\n\
         test\n\
         let m = garden(init, [PlantCrop(0, 0), SelectSeed(1), PlantCrop(0, \
         0)]) in\n\
         cropAt(m, 0, 0) == \"tomato\"\n\
         end;\n\n\
         hint \"select different seed\"\n\
         test\n\
         let m = garden(init, [SelectSeed(1), PlantCrop(0, 0)]) in\n\
         cropAt(m, 0, 0) == \"basil\"\n\
         end;\n\n\
         hint \"can harvest a crop\"\n\
         test\n\
         let m = garden(init, [PlantCrop(0, 0), HarvestCrop(0, 0)]) in\n\
         cropAt(m, 0, 0) == \"\"\n\
         end;\n\n\
         hint \"harvested cell has 0 health\"\n\
         test\n\
         let m = garden(init, [PlantCrop(0, 0), HarvestCrop(0, 0)]) in\n\
         healthAt(m, 0, 0) == 0\n\
         end;\n\n\
         hint \"tomato and basil are companions\"\n\
         test\n\
         companionEffect(\"tomato\", \"basil\") == Beneficial\n\
         end;\n\n\
         hint \"carrot and corn are companions\"\n\
         test\n\
         companionEffect(\"carrot\", \"corn\") == Beneficial\n\
         end;\n\n\
         hint \"tomato next to basil gains health\"\n\
         test\n\
         let m = garden(init, [\n\
         PlantCrop(0, 0),\n\
         SelectSeed(1),\n\
         PlantCrop(0, 1),\n\
         CalculateHealth\n\
         ]) in\n\
         healthAt(m, 0, 0) > 50\n\
         end;\n\n\
         hint \"basil next to tomato gains health\"\n\
         test\n\
         let m = garden(init, [\n\
         PlantCrop(0, 0),\n\
         SelectSeed(1),\n\
         PlantCrop(0, 1),\n\
         CalculateHealth\n\
         ]) in\n\
         healthAt(m, 0, 1) > 50\n\
         end;\n\n\
         hint \"tomato and carrot are rivals\"\n\
         test\n\
         companionEffect(\"tomato\", \"carrot\") == Harmful\n\
         end;\n\n\
         hint \"tomato next to carrot loses health\"\n\
         test\n\
         let m = garden(init, [\n\
         PlantCrop(1, 1),\n\
         SelectSeed(2),\n\
         PlantCrop(1, 0),\n\
         CalculateHealth\n\
         ]) in\n\
         healthAt(m, 1, 1) < 50\n\
         end;\n\n\
         hint \"same crop has no effect\"\n\
         test\n\
         companionEffect(\"tomato\", \"tomato\") == Neutral\n\
         end;\n\n\
         hint \"unrelated crops are neutral\"\n\
         test\n\
         companionEffect(\"sunflower\", \"corn\") == Neutral\n\
         end;\n\n\
         hint \"multiple companions stack benefits\"\n\
         test\n\
         let m = garden(init, [\n\
         PlantCrop(1, 1),\n\
         SelectSeed(1),\n\
         PlantCrop(0, 1),\n\
         PlantCrop(1, 0),\n\
         CalculateHealth\n\
         ]) in\n\
         healthAt(m, 1, 1) == 70\n\
         end;\n\n\
         hint \"mixed neighbors balance out\"\n\
         test\n\
         let m = garden(init, [\n\
         PlantCrop(1, 1),\n\
         SelectSeed(1),\n\
         PlantCrop(0, 1),\n\
         SelectSeed(2),\n\
         PlantCrop(1, 0),\n\
         CalculateHealth\n\
         ]) in\n\
         healthAt(m, 1, 1) == 50\n\
         end;\n\n\
         let moonGarden = garden(init, [\n\
         PlantCrop(1, 1),\n\
         SelectSeed(1),\n\
         PlantCrop(0, 1),\n\
         PlantCrop(1, 0),\n\
         SelectSeed(3),\n\
         PlantCrop(2, 2),\n\
         SelectSeed(2),\n\
         PlantCrop(2, 1),\n\
         CalculateHealth\n\
         ]) in\n\
         moonGarden\n";
      refractors = "()";
    } )
